from pathlib import Path

zones = [
 ('.','10.14.1.11', [('com','10.14.1.12'),('net','10.14.1.13')], []),
 ('com','10.14.1.12', [('example.com','10.14.1.14'),('service.com','10.14.2.11')], []),
 ('net','10.14.1.13', [('lab.net','10.14.2.12'),('tools.net','10.14.2.13')], []),
 ('example.com','10.14.1.14', [('shop.example.com','10.14.3.11')], ['www IN A 10.14.1.14','@ IN MX 10 mail.example.com.','mail IN A 10.14.1.14']),
 ('service.com','10.14.2.11', [('api.service.com','10.14.3.12')], ['@ IN MX 10 mail.service.com.','mail IN A 10.14.2.11']),
 ('lab.net','10.14.2.12', [('research.lab.net','10.14.3.13')], ['@ IN MX 10 mail.lab.net.','mail IN A 10.14.2.12']),
 ('tools.net','10.14.2.13', [('ci.tools.net','10.14.4.11')], ['@ IN MX 10 mail.tools.net.','mail IN A 10.14.2.13']),
 ('shop.example.com','10.14.3.11', [], ['@ IN A 10.14.3.11']),
 ('api.service.com','10.14.3.12', [], ['@ IN A 10.14.3.12']),
 ('research.lab.net','10.14.3.13', [('ai.research.lab.net','10.14.4.12'),('data.research.lab.net','10.14.4.13')], []),
 ('ci.tools.net','10.14.4.11', [], ['@ IN A 10.14.4.11']),
 ('ai.research.lab.net','10.14.4.12', [], ['@ IN A 10.14.4.12']),
 ('data.research.lab.net','10.14.4.13', [], ['@ IN A 10.14.4.13']),
]
for i,(zone,ip,children,records) in enumerate(zones,1):
    d=Path(f'pc{i}/etc/bind'); d.mkdir(parents=True, exist_ok=True)
    ns = 'ns.root.' if zone == '.' else f'ns.{zone}.'
    origin = zone if zone == '.' else zone+'.'
    lines=['"'$TTL 3600'"',f'"'$ORIGIN {origin}'"',f'@ IN SOA {ns} hostmaster.{\"root.\" if zone == \".\" else zone+\".\"} (', '    2026110101 3600 900 604800 300 )',f'@ IN NS {ns}',f'{ns} IN A {ip}']
    for child,addr in children:
        lines += [f'{child}. IN NS ns.{child}.', f'ns.{child}. IN A {addr}']
    lines += records
    (d/'db.zone').write_text('\\n'.join(lines)+'\\n')
    (d/'named.conf').write_text(f'''options {{
    directory \"/tmp\";
    pid-file \"/tmp/named.pid\";
    listen-on port 53 {{ any; }};
    listen-on-v6 {{ none; }};
    recursion no;
    allow-query {{ any; }};
    dnssec-validation no;
    empty-zones-enable no;
}};
zone \"{zone}\" {{ type primary; file \"/etc/bind/db.zone\"; }};
''')
    with Path(f'pc{i}.startup').open('a') as f: f.write('\\n# Start the authoritative DNS server.\\nnamed -4 -c /etc/bind/named.conf -u root\\n')
