    directory \"/tmp\";
    pid-file \"/tmp/named.pid\";
    listen-on port 53 { any; };
    listen-on-v6 { none; };
    recursion yes;
    allow-query { localhost; 10.14.5.12; 10.14.5.13; 10.14.6.11; 10.14.6.12; 10.14.6.13; };
    allow-recursion { localhost; 10.14.5.12; 10.14.5.13; 10.14.6.11; 10.14.6.12; 10.14.6.13; };
    dnssec-validation no;
    empty-zones-enable no;
};
zone \".\" { type hint; file \"/etc/bind/root.hints.lab\"; };
''')
(d/'root.hints.lab').write_text('. 3600 IN NS ns.root.\\nns.root. 3600 IN A 10.14.1.11\\n')
with Path('pc14.startup').open('a') as f: f.write('\\n# Start the recursive resolver using the lab root hints.\\nnamed -4 -c /etc/bind/named.conf -u root\\n')
